  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `committedUnits` int NOT NULL DEFAULT '0',
  `isIndefinite` tinyint(1) NOT NULL DEFAULT '1',
  `validUntil` datetime(3) DEFAULT NULL,
  `nextCommittedUnits` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Shift_cedisId_idx` (`cedisId`),
  CONSTRAINT `Shift_cedisId_fkey` FOREIGN KEY (`cedisId`) REFERENCES `Cedis` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Tabla: TireRotation
DROP TABLE IF EXISTS `TireRotation`;
