-- Tabla: Vehicle
DROP TABLE IF EXISTS `Vehicle`;
CREATE TABLE `Vehicle` (
  `id` int NOT NULL AUTO_INCREMENT,
  `plate` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `truckNumber` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('ACTIVE','MAINTENANCE','IN_TRANSIT') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `engine` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `yearModel` int DEFAULT NULL,
  `transmission` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fuelType` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vin` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `currentCedisId` int DEFAULT NULL,
  `brandId` int DEFAULT NULL,
  `fuelTypeId` int DEFAULT NULL,
  `transmissionId` int DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `Vehicle_plate_key` (`plate`),
  UNIQUE KEY `Vehicle_truckNumber_key` (`truckNumber`),
  UNIQUE KEY `Vehicle_vin_key` (`vin`),
  KEY `Vehicle_currentCedisId_fkey` (`currentCedisId`),
  KEY `Vehicle_brandId_fkey` (`brandId`),
  KEY `Vehicle_fuelTypeId_fkey` (`fuelTypeId`),
  KEY `Vehicle_transmissionId_fkey` (`transmissionId`),
  CONSTRAINT `Vehicle_brandId_fkey` FOREIGN KEY (`brandId`) REFERENCES `VehicleBrand` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Vehicle_currentCedisId_fkey` FOREIGN KEY (`currentCedisId`) REFERENCES `Cedis` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Vehicle_fuelTypeId_fkey` FOREIGN KEY (`fuelTypeId`) REFERENCES `FuelType` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Vehicle_transmissionId_fkey` FOREIGN KEY (`transmissionId`) REFERENCES `TransmissionType` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Tabla: VehicleBrand
